import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.annotation.JsonProperty;

public class JsonMapper {

    static class Spell {
        private String name;
        private String tier;
        private int damage;

        public Spell() {}
        public Spell(String name, String tier, int damage) {
            this.name = name; this.tier = tier; this.damage = damage;
        }
        public String getName() { return name; }
        public String getTier() { return tier; }
        public int getDamage() { return damage; }
        public void setName(String n) { this.name = n; }
        public void setTier(String t) { this.tier = t; }
        public void setDamage(int d) { this.damage = d; }
    }

    public static void main(String[] args) throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // 1. Serialise
        Spell blizzard = new Spell("Blizzard", "SENIOR", 250);


        // 2. Deserialise
        String json = "{\"name\":\"Frostbolt\",\"tier\":\"JUNIOR\",\"damage\":120}";


    }
}
